import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`call-prep`,heroTitle:`Prep your sales calls in minutes`,heroSubtitle:`Perplexity Computer researches prospects, maps value drivers, and builds your call brief - automatically.`,inputUrlCta:`Prep my call`,inputUrlPlaceholder:`e.g. prospect.com`,inputUrlPrefill:`Go to {url} and research this company thoroughly. Pull recent news, funding rounds, leadership changes, earnings signals, and tech stack data. Then build a comprehensive call prep brief that includes: 1) Company overview with key decision-makers, 2) Recent triggers and signals worth referencing, 3) Conversation starters tied to their current priorities, 4) Predicted objections with recommended responses, 5) Talk tracks that map their likely pain points to solution value drivers.`,heroOverlaySteps:[`Researching the company for recent news, funding, and leadership changes`,`Pulling tech stack data, earnings signals, and competitive positioning`,`Mapping prospect pain points to your solution's value drivers`,`Call brief, objection handlers, and talk tracks - ready to rehearse`],generatingSteps:[`Visiting {url} to pull company intel, news, and leadership data`,`Designing an agent to map prospect signals to conversation strategy`,`Configuring objection prediction and talk track generation`,`Setting up the call prep brief with starters, handlers, and value maps`],featureSectionTitle:`From prospect URL to call confidence`,featureCardTitles:[`Connects to your sales stack`,`Outputs you can use on the call`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Pipedrive, Google Sheets, Slack, Notion, Gmail - Computer plugs into your tools so research, prep, and follow-up happen in one workflow.`,`Company snapshot. Key stakeholder profiles. Conversation starters. Objection handlers with rebuttals. Talk tracks mapped to value drivers. Computer delivers a brief you can walk into any call with.`],capabilitySectionTitle:`Your sales researcher, on autopilot`,capabilitySectionSubtitle:`Paste a prospect, step away, come back to a complete call brief.`,capabilityCards:[{title:`Prospect Research`,description:`Computer can pull recent news, funding rounds, executive hires, and earnings signals - and summarize what matters for your conversation.`},{title:`Objection Mapping`,description:`Computer can predict likely objections based on company size, industry, and tech stack - and draft rebuttals tied to your value props.`},{title:`Talk Track Generation`,description:`Computer can write talk tracks that connect prospect pain points to your solution - tailored to the stakeholder you're meeting.`},{title:`Connect Your Tools`,description:`Computer can read and write to Pipedrive, Google Sheets, Gmail, Slack, and Notion - build workflows across your entire sales stack.`},{title:`Remember & Learn`,description:`Computer can remember your product positioning, ICPs, and past call outcomes across sessions - so every brief gets sharper over time.`},{title:`Monitor & Alert`,description:`Computer can watch prospect companies for trigger events - new funding, leadership changes, product launches - and ping you when it's time to reach out.`}]});export{t as default};
